import {regions,vehicleLabels} from './coastal-geography.js';
import {countryQuestions} from './coastal-learning.js';
export function installNetworkFeatures({root,map,side,controls,celebration,state,node,refresh,draw,engine,openVehicle,fresh}){
 const {stops,lineStops,routeCost,buyLine,extendLine,passengerJourney,roundReview}=engine;
 const makeButton=(label,action)=>{const b=node('button',label);b.type='button';b.onclick=action;return b;};
 function dialog(title){const d=node('dialog',null,'coastal-shop coastal-network-shop'),close=makeButton('Close '+title.toLowerCase()+' ×',()=>d.close());d.setAttribute('aria-label',title);d.append(close);root.append(d);let resume=false;d.addEventListener('close',()=>{if(!keepPreview)preview=null;keepPreview=false;if(resume&&!state.complete&&!state.failed&&!root.querySelector('dialog[open]'))state.running=true;resume=false;refresh();});return {d,open(){resume=state.running;state.running=false;refresh();d.showModal();}};}
 let preview=null,keepPreview=false;
 const mode=node('dialog',null,'coastal-shop coastal-mode-shop');mode.setAttribute('aria-label','Choose game mode');mode.addEventListener('cancel',e=>e.preventDefault());mode.append(node('h3','Choose your journey'),node('p','Both modes include geography quizzes, expanding maps and round cards.'));
 for(const [id,icon,title,description]of [['normal','☀','Normal','Build your network at the usual pace. No geography disruptions.'],['hard','🌧','Hard','Prepare for temporary floods, sea fog and festival crowds from round 3. Events give 12 seconds of warning.']]){const b=makeButton('',()=>{state.mode=id;state.event=null;mode.close();refresh();});b.dataset.mode=id;b.append(node('span',icon),node('strong',title),node('p',description));mode.append(b);}root.append(mode);
 const modeLabel=node('span',null,'coastal-mode-label');root.querySelector('.coastal-heading').append(modeLabel);
 const eventBox=node('section',null,'coastal-event-notice');eventBox.setAttribute('aria-live','polite');side.prepend(eventBox);
 const planner=dialog('Line planner'),planContent=node('div');planner.d.append(planContent);let plan=[],planType='road',extension=null;
 function renderPlan(){planContent.replaceChildren(node('h3',extension===null?'Plan a multi-stop line':'Extend your line'),node('p','One vehicle travels along the entire line and turns at the ends. Each section costs '+routeCost(state,planType)+' credits. Road crossings and water rules still apply.'));const chain=node('div',null,'coastal-line-chain');chain.textContent=plan.length?plan.map(id=>stops[id].name).join(' → '):'Choose your first stop';planContent.append(chain);const choices=node('div',null,'coastal-line-stops');for(const id of state.activeStops){const b=makeButton(stops[id].name,()=>{plan.push(id);renderPlan();});b.disabled=plan.includes(id);choices.append(b);}planContent.append(choices);const feedback=node('p',null,'coastal-plan-feedback'),count=extension===null?Math.max(0,plan.length-1):Math.max(0,plan.length-lineStops(state.links[extension]).length),purchase=makeButton('Build '+count+' section'+(count===1?'':'s')+' · '+count*routeCost(state,planType)+' credits',()=>{let issue;if(extension===null)issue=buyLine(state,plan,planType);else{const trial=structuredClone(state),old=lineStops(trial.links[extension]).length;for(const id of plan.slice(old)){issue=extendLine(trial,extension,id);if(issue)break;}if(!issue){state.links=trial.links;state.credits=trial.credits;}}if(issue){feedback.textContent=issue.message+' '+(issue.hint??'');return;}planner.d.close();refresh();});purchase.disabled=count===0;planContent.append(feedback,makeButton('Undo last stop',()=>{const min=extension===null?0:lineStops(state.links[extension]).length;if(plan.length>min)plan.pop();renderPlan();}),purchase);}
 const planButton=makeButton('Plan a line',()=>{extension=null;planType=state.tool;if(!['road','rail','highspeed'].includes(planType))planType='road';plan=[];renderPlan();planner.open();});controls.append(planButton);
 const inspector=dialog('Route performance'),inspectorContent=node('div');inspector.d.append(inspectorContent);
 function inspectLine(index){const link=state.links[index];if(!link)return;const stats=link.stats??{delivered:0,credits:0,travel:0,service:0,boarded:0};inspectorContent.replaceChildren(node('h3',vehicleLabels[link.type]+' line'),node('div',lineStops(link).map(id=>stops[id].name).join(' → '),'coastal-line-chain'),node('p','One vehicle · '+lineStops(link).length+' stops · '+link.cargo.length+' onboard'));const grid=node('dl',null,'coastal-vehicle-stats');for(const [label,value]of [['Delivered this round',stats.delivered],['Fare credits earned',stats.credits],['Boardings',stats.boarded],['Travelling',Math.round(stats.travel)+'s'],['Boarding / unloading',Math.round(stats.service)+'s']])grid.append(node('dt',label),node('dd',String(value)));inspectorContent.append(grid,node('p','Figures cover this round. Boarding time includes transfers; fares are earned when a passenger reaches their matching shape.'));if(['road','rail','highspeed'].includes(link.type))inspectorContent.append(makeButton('Extend line · '+routeCost(state,link.type)+' credits per section',()=>{inspector.d.close();extension=index;planType=link.type;plan=[...lineStops(link)];renderPlan();setTimeout(()=>planner.open(),0);}));inspectorContent.append(makeButton('Vehicle upgrades',()=>{inspector.d.close();setTimeout(()=>openVehicle(link.type),0);}));inspector.open();}
 const journey=dialog('Passenger journey'),journeyContent=node('div');journey.d.append(journeyContent);
 function inspectPassenger(id){const p=state.passengers[id];if(!p||p.mode==='delivered')return;preview=passengerJourney(state,p);journeyContent.replaceChildren(node('h3','Passenger journey'),node('p','Destination symbol: '+stops[p.destination].shape+' · '+Math.round(p.wait??0)+' seconds waiting'));if(!preview)journeyContent.append(node('p','No connected journey yet. Build a route to a matching destination symbol.'));else{journeyContent.append(node('div',preview.route.map(id=>stops[id].name).join(' → '),'coastal-line-chain'),node('p',preview.transfers.length?preview.transfers.length+' transfer'+(preview.transfers.length===1?'':'s')+' · Change at '+preview.transfers.map(id=>stops[id].name).join(', '):'Direct service: stay on the same line.'));const list=node('ol');for(const leg of preview.legs)list.append(node('li',vehicleLabels[leg.type]+' line '+(leg.line+1)+': '+stops[leg.a].name+' → '+stops[leg.b].name));journeyContent.append(list);}journeyContent.append(makeButton('Show journey on map',()=>{keepPreview=true;journey.d.close();draw();}));if(!journey.d.open)journey.open();else refresh();}
 const journeys=makeButton('Passenger journeys',()=>{journeyContent.replaceChildren(node('h3','Choose a waiting passenger'));for(const p of state.passengers.filter(p=>p.mode==='waiting'||p.mode==='boarding'))journeyContent.append(makeButton(stops[p.at].name+' · '+stops[p.destination].shape+' · '+Math.round(p.wait??0)+'s',()=>inspectPassenger(p.id)));if(!state.passengers.some(p=>p.mode==='waiting'||p.mode==='boarding'))journeyContent.append(node('p','No passengers are waiting. Tap a passenger symbol on the map during play.'));journeyContent.append(makeButton('Show journey on map',()=>{keepPreview=true;journey.d.close();draw();}));if(!journey.d.open)journey.open();else refresh();});side.append(journeys);
 const review=dialog('Round review'),reviewContent=node('div');review.d.append(reviewContent);
 function openReview(){const r=roundReview(state);reviewContent.replaceChildren(node('h3','Your network · Round '+state.round),node('p',r.busiest?'Busiest city: '+r.busiest.name+' · peak queue '+r.busiest.queue:'No queues recorded yet.'),node('p','Longest passenger wait: '+r.longestWait+'s'),node('p',r.best?'Most productive: '+r.best.stops.map(id=>stops[id].name).join(' → ')+' · '+r.best.delivered+' delivered · '+r.best.credits+' fare credits':'No deliveries recorded yet.'),node('p',r.tip,'coastal-review-tip'));const served=[...new Set(state.links.flatMap(lineStops).map(id=>stops[id].region))],region=served[state.round%Math.max(1,served.length)]??'england',q=countryQuestions(region)[state.round%3];reviewContent.append(node('h4','Geography check · '+regions.find(r=>r.id===region).name),node('p',q.prompt));const answer=node('p');for(const choice of [...q.options].sort((a,b)=>a.localeCompare(b))){const b=makeButton(choice,()=>{if(state.reviewQuiz)return;const correct=choice===q.options[0];state.reviewQuiz={correct,answer:choice};if(correct)state.credits+=5;answer.textContent=(correct?'Correct! +5 credits. ':'Answer: '+q.options[0]+'. ')+q.explanation;for(const b of reviewContent.querySelectorAll('[data-review-answer]'))b.disabled=true;refresh();});b.dataset.reviewAnswer=choice;b.disabled=Boolean(state.reviewQuiz)||!state.complete;reviewContent.append(b);}if(state.reviewQuiz)answer.textContent=(state.reviewQuiz.correct?'Correct! ':'Answer: '+q.options[0]+'. ')+q.explanation;else if(!state.complete)answer.textContent='Complete this round to answer for 5 credits.';reviewContent.append(answer);review.open();}
 const clearHighlight=makeButton('Clear journey highlight',()=>{preview=null;refresh();});side.append(clearHighlight,makeButton('Network review',openReview));celebration.append(makeButton('Review this round',()=>{celebration.hidden=true;openReview();}));
 function refreshFeatures(){clearHighlight.hidden=!preview;modeLabel.textContent=state.mode==='hard'?'Hard mode':'Normal mode';const e=state.event,visible=state.mode==='hard'&&e&&state.elapsed>=e.warningAt&&state.elapsed<e.end;eventBox.hidden=!visible;if(visible){const active=state.elapsed>=e.start;eventBox.dataset.active=String(active);eventBox.replaceChildren(node('strong',(active?'⚠ Active: ':'⚠ Coming: ')+e.title),node('p',(active?'Ends in '+Math.ceil(e.end-state.elapsed)+'s':'Starts in '+Math.ceil(e.start-state.elapsed)+'s')+' · '+e.advice),node('small','Geography: '+e.fact));}}
 return {inspectLine,inspectPassenger,refresh:refreshFeatures,get preview(){return preview;},chooseMode(){state.running=false;mode.showModal();},start(){if(fresh)queueMicrotask(()=>{if(root.isConnected)mode.showModal();});refreshFeatures();}};
}
